INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch02$PT147-S4-Q16$batch02$, 147, 4, 16, $batch02$Parallel Flaw$batch02$, $batch02$Voter: Our prime minister is evidently seeking a job at an international organization. Anyone seeking a job at an international organization would surely spend a lot of time traveling abroad, and our prime minister has spent more days abroad than at home so far this year.$batch02$, $batch02$Which one of the following arguments is most similar in its flawed reasoning to the voter’s argument?$batch02$, $batch02$D$batch02$, true, $batch02$Batch 02 approved 2026-10-01; question text from local bank.$batch02$ FROM lr_sections s WHERE s.preptest=147 AND s.section=4 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch02$PT147-S4-Q16$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch02$A$batch02$, $batch02$Kao must be a golfer. Kao is planning to run for office, and most people who run for office play golf.$batch02$, $batch02$Wrong Flaw$batch02$, false FROM lr_questions q WHERE q.qid=$batch02$PT147-S4-Q16$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch02$A$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch02$B$batch02$, $batch02$Franklin will lose the coming election. The opposing candidate has better policy ideas and brings more relevant experience to the job.$batch02$, $batch02$Wrong Flaw$batch02$, false FROM lr_questions q WHERE q.qid=$batch02$PT147-S4-Q16$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch02$B$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch02$C$batch02$, $batch02$Ramirez is evidently able to control the traffic signals. Just now, as Ramirez approached the curb, the traffic signal changed from red to green.$batch02$, $batch02$Wrong Flaw$batch02$, false FROM lr_questions q WHERE q.qid=$batch02$PT147-S4-Q16$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch02$C$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch02$D$batch02$, $batch02$Thompson must be negotiating a personal loan. Thompson was at the bank yesterday, and people who are negotiating a personal loan go to the bank to meet with a loan agent.$batch02$, $batch02$Correct$batch02$, true FROM lr_questions q WHERE q.qid=$batch02$PT147-S4-Q16$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch02$D$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch02$E$batch02$, $batch02$McKinsey must have committed a crime at some point. After all, despite extensive background checks no one has been able to show that McKinsey has never committed a crime.$batch02$, $batch02$Wrong Flaw$batch02$, false FROM lr_questions q WHERE q.qid=$batch02$PT147-S4-Q16$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch02$E$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch02$PT147-S4-Q16$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch02$Conclusion$batch02$, $batch02$The prime minister is seeking a job at an international organization.$batch02$), (1, $batch02$Evidence$batch02$, $batch02$Seeking such a job → lots of travel abroad. The prime minister travels abroad a lot.$batch02$), (2, $batch02$Evaluate$batch02$, $batch02$Diagram it: job seeking → travel. The prime minister has travel. The voter concludes job seeking. That runs the rule backward. Prime ministers travel for summits, trade talks and state visits. Plenty of things lead to travel. Lottery winners are wealthy, but not every wealthy person won the lottery.$batch02$), (3, $batch02$Goal$batch02$, $batch02$Find an argument with a rule "X → Y," a case of Y, and a conclusion of X.$batch02$)) v(position,label,body) WHERE q.qid=$batch02$PT147-S4-Q16$batch02$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch02$A$batch02$, $batch02$Kao has the *sufficient* side (running for office) and the conclusion is the other side (golfer). The direction is right. The weakness is that "most" does not mean "all." That is a different flaw.$batch02$), ($batch02$B$batch02$, $batch02$There is no conditional at all. This is a prediction from comparative strengths, not a reversed rule.$batch02$), ($batch02$C$batch02$, $batch02$This infers a cause from one coincidence in timing. The voter's argument is conditional, not causal.$batch02$), ($batch02$D$batch02$, $batch02$Rule: negotiating a loan → go to the bank. Thompson went to the bank. Conclusion: Thompson is negotiating a loan. Same reversal, same shape: people visit banks for many reasons, just as prime ministers travel for many reasons.$batch02$), ($batch02$E$batch02$, $batch02$This treats a claim not proven false (never committed a crime) as proof of its opposite. That is the unproven vs proven false flaw, not a reversal.$batch02$)) v(letter,body) WHERE q.qid=$batch02$PT147-S4-Q16$batch02$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
